from skfem import *
from skfem.helpers import dot, grad

mesh = MeshTri().refined(4)
basis = Basis(mesh, ElementTriP1())

@BilinearForm
def laplace(u, v, _):
    return dot(grad(u), grad(v))

@LinearForm
def rhs(v, _):
    return 1. * v

A = laplace.assemble(basis)
b = rhs.assemble(basis)
A, b = enforce(A, b, D=mesh.boundary_nodes())
x = solve(A, b)
